const uploads = $input.all().map((item) => {
  const data = item && typeof item.json === "object" && item.json !== null
    ? item.json
    : {};
  return data;
});

if (uploads.length < 2) {
  throw new Error("Expected two Cloudinary upload items.");
}

const textValue = (item, key) => {
  const value = item[key];
  return value == null ? "" : String(value).toLowerCase();
};

const isTexUpload = (item) => {
  const publicId = textValue(item, "public_id");
  const secureUrl = textValue(item, "secure_url");
  const url = textValue(item, "url");

  return (
    publicId.endsWith(".tex") ||
    secureUrl.endsWith(".tex") ||
    url.endsWith(".tex")
  );
};

const isPdfUpload = (item) => {
  const fileFormat = textValue(item, "format");
  const publicId = textValue(item, "public_id");
  const secureUrl = textValue(item, "secure_url");
  const url = textValue(item, "url");

  return (
    fileFormat === "pdf" ||
    publicId.endsWith(".pdf") ||
    secureUrl.endsWith(".pdf") ||
    url.endsWith(".pdf")
  );
};

const texUpload = uploads.find(isTexUpload);
const pdfUpload = uploads.find(isPdfUpload);

if (!texUpload) {
  throw new Error("Could not identify the TEX upload result.");
}

if (!pdfUpload) {
  throw new Error("Could not identify the PDF upload result.");
}

const texUrl = texUpload.secure_url || texUpload.url;
const pdfUrl = pdfUpload.secure_url || pdfUpload.url;

if (!texUrl || !pdfUrl) {
  throw new Error("Cloudinary did not return both TEX and PDF URLs.");
}

const source = $("Normalize Input").first().json;

return [
  {
    json: {
      document_type: source.document_type,
      application_id: source.application_id,
      job_id: source.job_id,
      company_name: source.company_name,
      job_title: source.job_title,
      tex_url: texUrl,
      pdf_url: pdfUrl,
      tex_public_id: texUpload.public_id,
      pdf_public_id: pdfUpload.public_id,
    },
  },
];
